3	# KVStore: 키-값 저장소
4	struct KVEntry {
5	  key: String
6	  value: String
7	}
8	
9	struct KVStore {
10	  entries: Array<KVEntry>
11	}
12	
13	# FreqTable: 빈도 테이블
14	struct FreqEntry {
15	  key: String
16	  count: Int
17	}
18	
19	struct FreqTable {
20	  entries: Array<FreqEntry>
21	}
22	
23	# ============================================================
24	# FNV-1a 해시 (32bit) — profiler/pattern.go에서 이식
25	# ============================================================
26	@inline
27	func fnv1a_hash(s: String) -> Int {
28	  var h: Int = 2166136261  # FNV offset basis (32bit)
29	  var i: Int = 0
30	  var len: Int = string_len(s)
31	
32	  while i < len {
33	    var byte_val: Int = string_byte(s, i)
34	    h = (h ^ byte_val) * 16777619  # FNV prime
35	    i = i + 1
36	  }
37	
38	  return h
39	}
