41	# ============================================================
42	# KV Store 함수들
43	# ============================================================
44	
45	func kv_new() -> KVStore {
46	  var store: KVStore = {entries: array_new()}
47	  return store
48	}
49	
50	func kv_get(store: KVStore, key: String) -> String {
51	  var i: Int = 0
52	  var len: Int = array_len(store.entries)
53	
54	  while i < len {
55	    var entry: KVEntry = array_get(store.entries, i)
56	    if string_eq(entry.key, key) {
57	      return entry.value
58	    }
59	    i = i + 1
60	  }
61	
62	  return ""  # 없음
63	}
64	
65	func kv_set(store: KVStore, key: String, val: String) -> KVStore {
66	  var i: Int = 0
67	  var len: Int = array_len(store.entries)
68	
69	  # 기존 키 업데이트
70	  while i < len {
71	    var entry: KVEntry = array_get(store.entries, i)
72	    if string_eq(entry.key, key) {
73	      entry.value = val
74	      array_set(store.entries, i, entry)
75	      return store
76	    }
77	    i = i + 1
78	  }
79	
80	  # 새 항목 추가
81	  var new_entry: KVEntry = {key: key, value: val}
82	  array_push(store.entries, new_entry)
83	
84	  return store
85	}
86	
87	func kv_exists(store: KVStore, key: String) -> Bool {
88	  var val: String = kv_get(store, key)
89	  return !string_eq(val, "")
90	}
