92	# ============================================================
93	# Frequency Table 함수들
94	# ============================================================
95	
96	func freq_new() -> FreqTable {
97	  var table: FreqTable = {entries: array_new()}
98	  return table
99	}
100	
101	func freq_increment(table: FreqTable, key: String) -> FreqTable {
102	  var i: Int = 0
103	  var len: Int = array_len(table.entries)
104	
105	  # 기존 항목 증가
106	  while i < len {
107	    var entry: FreqEntry = array_get(table.entries, i)
108	    if string_eq(entry.key, key) {
109	      entry.count = entry.count + 1
110	      array_set(table.entries, i, entry)
111	      return table
112	    }
113	    i = i + 1
114	  }
115	
116	  # 새 항목 생성
117	  var new_entry: FreqEntry = {key: key, count: 1}
118	  array_push(table.entries, new_entry)
119	
120	  return table
121	}
122	
123	func freq_get(table: FreqTable, key: String) -> Int {
124	  var i: Int = 0
125	  var len: Int = array_len(table.entries)
126	
127	  while i < len {
128	    var entry: FreqEntry = array_get(table.entries, i)
129	    if string_eq(entry.key, key) {
130	      return entry.count
131	    }
132	    i = i + 1
133	  }
134	
135	  return 0
136	}
137	
138	# 상위 N개 키 반환 (count 기준 내림차순)
139	func freq_top(table: FreqTable, n: Int) -> Array<String> {
140	  var result: Array<String> = array_new()
141	  var sorted: Array<FreqEntry> = array_copy(table.entries)
142	
143	  # 간단한 버블정렬 (내림차순)
144	  var i: Int = 0
145	  var len: Int = array_len(sorted)
146	  while i < len {
147	    var j: Int = 0
148	    while j < len - i - 1 {
149	      var e1: FreqEntry = array_get(sorted, j)
150	      var e2: FreqEntry = array_get(sorted, j + 1)
151	      if e1.count < e2.count {
152	        # 스왑
153	        array_set(sorted, j, e2)
154	        array_set(sorted, j + 1, e1)
155	      }
156	      j = j + 1
157	    }
158	    i = i + 1
159	  }
160	
161	  # 상위 N개 추출
162	  i = 0
163	  while i < n && i < array_len(sorted) {
164	    var entry: FreqEntry = array_get(sorted, i)
165	    array_push(result, entry.key)
166	    i = i + 1
167	  }
168	
169	  return result
170	}
