192	func string_contains(s: String, substr: String) -> Bool {
193	  var i: Int = 0
194	  var s_len: Int = string_len(s)
195	  var sub_len: Int = string_len(substr)
196	
197	  while i <= s_len - sub_len {
198	    var j: Int = 0
199	    var match: Bool = true
200	
201	    while j < sub_len {
202	      if string_byte(s, i + j) != string_byte(substr, j) {
203	        match = false
204	        break
205	      }
206	      j = j + 1
207	    }
208	
209	    if match {
210	      return true
211	    }
212	    i = i + 1
213	  }
214	
215	  return false
216	}
