257	func string_split(s: String, sep: String) -> Array<String> {
258	  var parts: Array<String> = array_new()
259	  var current: String = ""
260	  var i: Int = 0
261	  var sep_len: Int = string_len(sep)
262	
263	  while i < string_len(s) {
264	    if string_contains(s[i:], sep) {
265	      var idx: Int = i
266	      while idx < string_len(s) && !string_contains(s[idx:], sep) {
267	        current = current + string(s[idx])
268	        idx = idx + 1
269	      }
270	      array_push(parts, current)
271	      current = ""
272	      i = idx + sep_len
273	    } else {
274	      current = current + string(s[i])
275	      i = i + 1
276	    }
277	  }
278	
279	  if !string_eq(current, "") {
280	    array_push(parts, current)
281	  }
282	
283	  return parts
284	}
