280	    // === Select 패턴 (채널 멀티플렉서) ===
281	
282	    // 첫 번째로 메시지가 있는 채널에서 수신
283	    func chan_select(channels: [Channel]) -> SelectResult {
284	        let i = 0;
285	        for i = 0; i < len(channels); i = i + 1 {
286	            if !channels[i].chan_is_empty() {
287	                let val, ok = channels[i].chan_recv();
288	                return SelectResult{ channel_idx: i32(i), value: val, ok: ok };
289	            }
290	        }
291	        return SelectResult{ channel_idx: -1, value: 0, ok: false };
292	    }
293	
294	    // === 글로벌 편의 함수 ===
295	
296	    // 스케줄러 없이 독립적 Actor 생성
297	    func spawn(buffer_size: i32) -> Actor {
