302	    func wait_actor(a: *Actor, max_ticks: i32) -> (i64, bool) {
303	        let t = 0;
304	        for t = 0; t < max_ticks; t = t + 1 {
305	            if a.actor_is_done() {
306	                return (a.result, true);
307	            }
308	            a.actor_tick();
309	        }
310	        return (0, false);
311	    }
