325	        let state_str = if a.state == ACTOR_DONE { "DONE" } else { "ACTIVE" };
326	        print("[Actor " + i32_to_string(a.id) + "] state=" + state_str + " inbox_len=" + i32_to_string(a.inbox.chan_len()));
