4	// 목표: ASM 코드제너레이터가 생성한 바이트코드를 실행하는 스택 기반 가상 머신 구현
5	// 원리:
6	//   1. 32개 레지스터 (r0-r31)와 512-entry 스택을 사용한 스택 기반 VM
7	//   2. 바이트코드는 i32 배열로 표현, 각 명령어는 opcode + operand로 구성
8	//   3. 플래그 레지스터는 CMP 결과를 저장 (0=zero, -1=neg, 1=pos)
9	//   4. vm_execute로 전체 실행, vm_step으로 단계별 실행 가능
10	// 구조:
11	//   - 에러 상수 정의 (VM_ERR_* 120-123)
12	//   - 주요 구조체 (VMContext, VirtualMachine)
13	//   - 공개 API (vm_new, vm_load_bytecode, vm_execute, vm_step, vm_push, vm_pop 등)
14	//   - 내부 헬퍼 (opcode 추출, 플래그 계산, 유효성 검사)
15	// ============================================================================
16	
17	module vm {
18	    // === 에러 코드 ===
19	    const VM_OK:           i32 = 0;     // 정상 완료
20	    const VM_ERR_STACK:    i32 = 120;   // 스택 오버플로우/언더플로우
21	    const VM_ERR_REGS:     i32 = 121;   // 잘못된 레지스터 인덱스
22	    const VM_ERR_INVALID:  i32 = 122;   // 잘못된 명령어 또는 바이트코드
23	    const VM_ERR_OVERFLOW: i32 = 123;   // 레지스터 오버플로우
24	
25	    // === 상수 ===
26	    const MAX_STACK:       i32 = 512;   // 스택 최대 엔트리 수
27	    const MAX_REGS:        i32 = 32;    // 레지스터 개수
28	    const MAX_FRAMES:      i32 = 16;    // 호출 스택 깊이 (CALL/RET용)
29	
30	    // === ASM opcode 정의 ===
31	    const ASM_LOAD:    i32 = 1;         // LOAD: regs[dst] = imm
32	    const ASM_ADD:     i32 = 2;         // ADD: regs[dst] = regs[src1] + regs[src2]
33	    const ASM_SUB:     i32 = 3;         // SUB: regs[dst] = regs[src1] - regs[src2]
34	    const ASM_MUL:     i32 = 4;         // MUL: regs[dst] = regs[src1] * regs[src2]
35	    const ASM_DIV:     i32 = 5;         // DIV: regs[dst] = regs[src1] / regs[src2]
36	    const ASM_CMP:     i32 = 6;         // CMP: flags = sign(regs[src1] - regs[src2])
37	    const ASM_JMP:     i32 = 7;         // JMP: ip = addr
38	    const ASM_JZ:      i32 = 8;         // JZ: if flags == 0, ip = addr
39	    const ASM_CALL:    i32 = 9;         // CALL: push(ip), ip = addr
40	    const ASM_RET:     i32 = 10;        // RET: ip = pop()
41	    const ASM_PUSH:    i32 = 11;        // PUSH: push(regs[src])
42	    const ASM_POP:     i32 = 12;        // POP: regs[dst] = pop()
43	
44	    // === 데이터 구조체 ===
45	    // VM 실행 컨텍스트
46	    struct VMContext {
47	        regs:    [i64];     // 32개 레지스터
48	        stack:   [i64];     // 512-entry 스택
49	        sp:      i32;       // 스택 포인터 (다음 쓸 위치)
50	        ip:      i32;       // 명령어 포인터
51	        flags:   i32;       // CMP 플래그 (0=zero, -1=neg, 1=pos)
52	    }
53	
54	    // 가상 머신 인스턴스
55	    struct VirtualMachine {
56	        bytecode:      [i32];      // 바이트코드 배열
57	        bytecode_len:  i32;        // 바이트코드 길이
58	        ctx:           VMContext;  // 실행 컨텍스트
59	        error:         i32;        // 최근 에러 코드
60	    }
61	
62	    // === 내부 헬퍼 함수 ===
63	
64	    // 플래그 계산: a - b의 부호 반환
65	    // 반환: a > b → 1, a == b → 0, a < b → -1
66	    @inline
67	    func compute_flags(a: i64, b: i64) -> i32 {
68	        let diff = a - b;
69	        if diff > 0 {
70	            return 1;
71	        } else if diff == 0 {
72	            return 0;
73	        } else {
74	            return -1;
75	        }
76	    }
77	
78	    // i32 배열에서 opcode 추출 (상위 비트에서 opcode 추출)
79	    @inline
80	    func extract_opcode(instr: i32) -> i32 {
81	        return (instr >> 24) & 0xFF;
82	    }
83	
84	    // i32 배열에서 dst 오퍼랜드 추출
85	    @inline
86	    func extract_dst(instr: i32) -> i32 {
87	        return (instr >> 16) & 0xFF;
88	    }
89	
90	    // i32 배열에서 src1 오퍼랜드 추출
91	    @inline
92	    func extract_src1(instr: i32) -> i32 {
93	        return (instr >> 8) & 0xFF;
94	    }
95	
96	    // i32 배열에서 src2 오퍼랜드 추출
97	    @inline
98	    func extract_src2(instr: i32) -> i32 {
99	        return instr & 0xFF;
100	    }
101	
102	    // i32 배열에서 imm(immediate) 값 추출
103	    @inline
104	    func extract_imm(instr: i32) -> i32 {
105	        return instr & 0xFFFFFF;
106	    }
107	
108	    // === 공개 API ===
109	
110	    // 새 가상 머신 인스턴스 생성
111	    func vm_new() -> VirtualMachine {
112	        let regs = make([i64], MAX_REGS);
113	        let stack = make([i64], MAX_STACK);
114	        let i = 0;
115	
116	        // 레지스터 초기화
117	        for i = 0; i < MAX_REGS; i = i + 1 {
118	            regs[i] = i64(0);
119	        }
120	
121	        // 스택 초기화
122	        for i = 0; i < MAX_STACK; i = i + 1 {
123	            stack[i] = i64(0);
124	        }
125	
126	        let ctx = VMContext{
127	            regs:   regs,
128	            stack:  stack,
129	            sp:     0,
130	            ip:     0,
131	            flags:  0,
132	        };
133	
134	        let vm = VirtualMachine{
135	            bytecode:      make([i32], 0),
136	            bytecode_len:  0,
137	            ctx:           ctx,
138	            error:         VM_OK,
139	        };
140	
141	        return vm;
142	    }
143	
144	    // 바이트코드 로드
145	    // bytecode: 로드할 i32 바이트코드 배열
146	    // len: 바이트코드 길이
147	    // 반환: VM_OK 또는 에러 코드
148	    func vm_load_bytecode(vm: *VirtualMachine, bytecode: [i32], len: i32) -> i32 {
149	        if len < 0 {
150	            vm.error = VM_ERR_INVALID;
151	            return VM_ERR_INVALID;
152	        }
153	
154	        vm.bytecode = bytecode;
155	        vm.bytecode_len = len;
156	        vm.ctx.ip = 0;
157	
158	        return VM_OK;
159	    }
160	
161	    // 스택에 값 푸시
162	    // 성공: VM_OK, 스택 오버플로우: VM_ERR_STACK
163	    func vm_push(vm: *VirtualMachine, val: i64) -> i32 {
164	        if vm.ctx.sp >= MAX_STACK {
165	            vm.error = VM_ERR_STACK;
166	            return VM_ERR_STACK;
167	        }
168	
169	        vm.ctx.stack[vm.ctx.sp] = val;
170	        vm.ctx.sp = vm.ctx.sp + 1;
171	
172	        return VM_OK;
173	    }
174	
175	    // 스택에서 값 팝
176	    // 반환: (값, VM_OK) 또는 (0, VM_ERR_STACK)
177	    func vm_pop(vm: *VirtualMachine) -> (i64, i32) {
178	        if vm.ctx.sp <= 0 {
179	            vm.error = VM_ERR_STACK;
180	            return (i64(0), VM_ERR_STACK);
181	        }
182	
183	        vm.ctx.sp = vm.ctx.sp - 1;
184	        let val = vm.ctx.stack[vm.ctx.sp];
185	
186	        return (val, VM_OK);
187	    }
188	
189	    // 레지스터 값 조회
190	    // 성공: (값, VM_OK), 범위 초과: (0, VM_ERR_REGS)
191	    func vm_get_reg(vm: *VirtualMachine, reg_id: i32) -> (i64, i32) {
192	        if reg_id < 0 || reg_id >= MAX_REGS {
193	            vm.error = VM_ERR_REGS;
194	            return (i64(0), VM_ERR_REGS);
195	        }
196	
197	        return (vm.ctx.regs[reg_id], VM_OK);
198	    }
199	
200	    // 레지스터에 값 설정
201	    // 성공: VM_OK, 범위 초과: VM_ERR_REGS
202	    func vm_set_reg(vm: *VirtualMachine, reg_id: i32, val: i64) -> i32 {
203	        if reg_id < 0 || reg_id >= MAX_REGS {
204	            vm.error = VM_ERR_REGS;
205	            return VM_ERR_REGS;
206	        }
207	
208	        vm.ctx.regs[reg_id] = val;
209	        return VM_OK;
210	    }
211	
212	    // 반환값 조회 (r1 레지스터 반환)
213	    func vm_get_result(vm: *VirtualMachine) -> i64 {
214	        if 1 >= MAX_REGS {
215	            return i64(0);
216	        }
217	        return vm.ctx.regs[1];
218	    }
219	
220	    // VM 상태 초기화
221	    func vm_reset(vm: *VirtualMachine) -> i32 {
222	        let i = 0;
223	
224	        // 레지스터 초기화
225	        for i = 0; i < MAX_REGS; i = i + 1 {
226	            vm.ctx.regs[i] = i64(0);
227	        }
228	
229	        // 스택 초기화
230	        for i = 0; i < MAX_STACK; i = i + 1 {
231	            vm.ctx.stack[i] = i64(0);
232	        }
233	
234	        vm.ctx.sp = 0;
235	        vm.ctx.ip = 0;
236	        vm.ctx.flags = 0;
237	        vm.error = VM_OK;
238	
239	        return VM_OK;
240	    }
241	
242	    // 단일 명령어 실행
243	    // 성공: VM_OK, 실패: 에러 코드
244	    func vm_step(vm: *VirtualMachine) -> i32 {
245	        // IP가 바이트코드 범위를 벗어났는지 확인
246	        if vm.ctx.ip >= vm.bytecode_len {
247	            vm.error = VM_ERR_INVALID;
248	            return VM_ERR_INVALID;
249	        }
250	
251	        let instr = vm.bytecode[vm.ctx.ip];
252	        vm.ctx.ip = vm.ctx.ip + 1;
253	
254	        let opcode = extract_opcode(instr);
255	        let dst = extract_dst(instr);
256	        let src1 = extract_src1(instr);
257	        let src2 = extract_src2(instr);
258	        let imm = extract_imm(instr);
259	
260	        // 범위 검사
261	        if dst >= MAX_REGS || src1 >= MAX_REGS || src2 >= MAX_REGS {
262	            vm.error = VM_ERR_REGS;
263	            return VM_ERR_REGS;
264	        }
265	
266	        // opcode별 실행
267	        if opcode == ASM_LOAD {
268	            // LOAD: regs[dst] = imm (i32를 i64로 확장)
269	            vm.ctx.regs[dst] = i64(imm);
270	            return VM_OK;
271	
272	        } else if opcode == ASM_ADD {
273	            // ADD: regs[dst] = regs[src1] + regs[src2]
274	            let val1 = vm.ctx.regs[src1];
275	            let val2 = vm.ctx.regs[src2];
276	            vm.ctx.regs[dst] = val1 + val2;
277	            return VM_OK;
278	
279	        } else if opcode == ASM_SUB {
280	            // SUB: regs[dst] = regs[src1] - regs[src2]
281	            let val1 = vm.ctx.regs[src1];
282	            let val2 = vm.ctx.regs[src2];
283	            vm.ctx.regs[dst] = val1 - val2;
284	            return VM_OK;
285	
286	        } else if opcode == ASM_MUL {
287	            // MUL: regs[dst] = regs[src1] * regs[src2]
288	            let val1 = vm.ctx.regs[src1];
289	            let val2 = vm.ctx.regs[src2];
290	            vm.ctx.regs[dst] = val1 * val2;
291	            return VM_OK;
292	
293	        } else if opcode == ASM_DIV {
294	            // DIV: regs[dst] = regs[src1] / regs[src2]
295	            let val1 = vm.ctx.regs[src1];
296	            let val2 = vm.ctx.regs[src2];
297	            if val2 == 0 {
298	                vm.error = VM_ERR_INVALID;
299	                return VM_ERR_INVALID;
300	            }
301	            vm.ctx.regs[dst] = val1 / val2;
302	            return VM_OK;
303	
304	        } else if opcode == ASM_CMP {
305	            // CMP: flags = sign(regs[src1] - regs[src2])
306	            let val1 = vm.ctx.regs[src1];
307	            let val2 = vm.ctx.regs[src2];
308	            vm.ctx.flags = compute_flags(val1, val2);
309	            return VM_OK;
310	
311	        } else if opcode == ASM_JMP {
312	            // JMP: ip = imm (주소로 점프)
313	            vm.ctx.ip = imm;
314	            return VM_OK;
315	
316	        } else if opcode == ASM_JZ {
317	            // JZ: if flags == 0, ip = imm
318	            if vm.ctx.flags == 0 {
319	                vm.ctx.ip = imm;
320	            }
321	            return VM_OK;
322	
323	        } else if opcode == ASM_CALL {
324	            // CALL: push(ip), ip = imm
325	            let err = vm_push(vm, i64(vm.ctx.ip));
326	            if err != VM_OK {
327	                vm.error = err;
328	                return err;
329	            }
330	            vm.ctx.ip = imm;
331	            return VM_OK;
332	
333	        } else if opcode == ASM_RET {
334	            // RET: ip = pop()
335	            let addr, err = vm_pop(vm);
336	            if err != VM_OK {
337	                vm.error = err;
338	                return err;
339	            }
340	            vm.ctx.ip = i32(addr);
341	            return VM_OK;
342	
343	        } else if opcode == ASM_PUSH {
344	            // PUSH: push(regs[src1])
345	            let val = vm.ctx.regs[src1];
346	            let err = vm_push(vm, val);
347	            if err != VM_OK {
348	                vm.error = err;
349	                return err;
350	            }
351	            return VM_OK;
352	
353	        } else if opcode == ASM_POP {
354	            // POP: regs[dst] = pop()
355	            let val, err = vm_pop(vm);
356	            if err != VM_OK {
357	                vm.error = err;
358	                return err;
359	            }
360	            vm.ctx.regs[dst] = val;
361	            return VM_OK;
362	
363	        } else {
364	            // 알 수 없는 opcode
365	            vm.error = VM_ERR_INVALID;
366	            return VM_ERR_INVALID;
367	        }
368	    }
369	
370	    // 전체 바이트코드 실행 (RET까지 또는 bytecode_len 도달)
371	    func vm_execute(vm: *VirtualMachine) -> i32 {
372	        let err = VM_OK;
373	
374	        while vm.ctx.ip < vm.bytecode_len {
375	            err = vm_step(vm);
376	            if err != VM_OK {
377	                return err;
378	            }
379	
380	            // RET 명령어 실행 후 종료
381	            let current_ip = vm.ctx.ip - 1;
382	            if current_ip >= 0 && current_ip < vm.bytecode_len {
383	                let instr = vm.bytecode[current_ip];
384	                let opcode = extract_opcode(instr);
385	                if opcode == ASM_RET {
386	                    return VM_OK;
387	                }
388	            }
389	        }
390	
391	        return VM_OK;
392	    }
