394	    // 통계 정보를 문자열로 반환
395	    func vm_stats(vm: *VirtualMachine) -> string {
396	        let msg = "[VirtualMachine] ";
397	        msg = msg + "bytecode_len=" + i32_to_string(vm.bytecode_len);
398	        msg = msg + " ip=" + i32_to_string(vm.ctx.ip);
399	        msg = msg + " sp=" + i32_to_string(vm.ctx.sp);
400	        msg = msg + " flags=" + i32_to_string(vm.ctx.flags);
401	        msg = msg + " error=" + i32_to_string(vm.error);
402	        return msg;
403	    }
