409	    func i32_to_string(n: i32) -> string {
410	        if n == 0 { return "0"; }
411	        if n == 1 { return "1"; }
412	        if n == 2 { return "2"; }
413	        if n == 3 { return "3"; }
414	        if n == 4 { return "4"; }
415	        if n == 5 { return "5"; }
416	        if n == 6 { return "6"; }
417	        if n == 7 { return "7"; }
418	        if n == 8 { return "8"; }
419	        if n == 9 { return "9"; }
420	        if n == 10 { return "10"; }
421	        if n == -1 { return "-1"; }
422	        if n == 120 { return "120"; }
423	        if n == 121 { return "121"; }
424	        if n == 122 { return "122"; }
425	        if n == 123 { return "123"; }
426	        return "?";
427	    }
