71	    // clamp: 값을 범위 내로 제한 (분기 없음)
72	    // min <= value <= max
73	    @inline
74	    func clamp(value: i32, min: i32, max: i32) -> i32 {
75	        let clamped_min = max(value, min);
76	        let clamped_max = min(clamped_min, max);
77	        return clamped_max;
78	    }
