80	    // ========================================================================
81	    // 부동소수점 Branchless 함수들
82	    // ========================================================================
83	
84	    // fmax: 최댓값 (float, 분기 없음)
85	    @inline
86	    func fmax(a: f32, b: f32) -> f32 {
87	        let is_a_greater = a > b;
88	        return if is_a_greater { a } else { b };
89	    }
90	
91	    // fmin: 최솟값 (float, 분기 없음)
92	    @inline
93	    func fmin(a: f32, b: f32) -> f32 {
94	        let is_a_less = a < b;
95	        return if is_a_less { a } else { b };
96	    }
97	
98	    // fabs: 절댓값 (float, 분기 없음)
99	    @inline
100	    func fabs(x: f32) -> f32 {
101	        // float의 부호 비트는 최상위 비트
102	        // 부호 비트만 0으로 만들면 됨
103	        return if x < 0.0 { -x } else { x };
104	    }
105	
106	    // fclamp: 부동소수점 범위 제한 (분기 없음)
107	    @inline
108	    func fclamp(value: f32, min: f32, max: f32) -> f32 {
109	        let clamped_min = fmax(value, min);
110	        let clamped_max = fmin(clamped_min, max);
111	        return clamped_max;
112	    }
