115	    // 벡터 연산에 최적화된 Branchless 함수들
116	    // ========================================================================
117	
118	    // step: 계단 함수 (분기 없음)
119	    // x < edge 이면 0.0, 아니면 1.0
120	    @inline
121	    func step(edge: f32, x: f32) -> f32 {
122	        return if x < edge { 0.0 } else { 1.0 };
123	    }
124	
125	    // smoothstep: 부드러운 계단 함수 (분기 없음)
126	    // 0 <= x <= 1 사이에서 부드럽게 보간
127	    @inline
128	    func smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
129	        let t = fclamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
130	        return t * t * (3.0 - 2.0 * t);
131	    }
132	
133	    // mix: 선형 보간 (분기 없음)
134	    // result = a + (b - a) * t
135	    @inline
136	    func mix(a: f32, b: f32, t: f32) -> f32 {
137	        return a + (b - a) * t;
138	    }
139	
140	    // is_finite: 유한수 판정 (분기 없음)
141	    @inline
142	    func is_finite(x: f32) -> bool {
143	        // NaN과 무한대는 특정 비트 패턴
144	        // 실제 구현에서는 IEEE 754 비트 확인
145	        return x == x && x != f32(1.0)/0.0;
146	    }
