152	    // clamp_array: 배열의 모든 값을 범위 내로 제한
153	    func clamp_array(arr: [i32], min: i32, max: i32) -> [i32] {
154	        let result = make([i32], len(arr));
155	
156	        for i = 0; i < len(arr); i = i + 1 {
157	            result[i] = clamp(arr[i], min, max);
158	        }
159	
