164	    func fclamp_array(arr: [f32], min: f32, max: f32) -> [f32] {
165	        let result = make([f32], len(arr));
166	
167	        for i = 0; i < len(arr); i = i + 1 {
168	            result[i] = fclamp(arr[i], min, max);
169	        }
170	
171	        return result;
