174	    // abs_array: 배열의 모든 절댓값
175	    func abs_array(arr: [i32]) -> [i32] {
176	        let result = make([i32], len(arr));
177	
178	        for i = 0; i < len(arr); i = i + 1 {
179	            result[i] = abs(arr[i]);
180	        }
