185	    // fabs_array: float 배열 절댓값
186	    func fabs_array(arr: [f32]) -> [f32] {
187	        let result = make([f32], len(arr));
188	
189	        for i = 0; i < len(arr); i = i + 1 {
190	            result[i] = fabs(arr[i]);
