196	    // conditional_mul: 조건에 따른 곱셈 (분기 없음)
197	    // condition이 true이면 a * b, 아니면 a
198	    func conditional_mul(arr: [f32], condition_arr: [bool], multiplier: f32) -> [f32] {
199	        let result = make([f32], len(arr));
200	
201	        for i = 0; i < len(arr); i = i + 1 {
202	            let cond_bit = if condition_arr[i] { 1.0 } else { 0.0 };
203	            result[i] = arr[i] * (1.0 + (multiplier - 1.0) * cond_bit);
204	        }
205	
206	        return result;
207	    }
