220	    // Vector3DArray 구조체
221	    struct Vector3DArray {
222	        x_data: [f32];
223	        y_data: [f32];
224	        z_data: [f32];
225	        count: u32;
226	    }
227	
228	    // clamp_vectors: 벡터 배열의 모든 성분을 범위 내로 제한
229	    // SIMD 마스킹으로 최적화됨
230	    func clamp_vectors(va: *Vector3DArray, min: f32, max: f32) -> Vector3DArray {
231	        let result = Vector3DArray {
232	            x_data: make([f32], va.count),
233	            y_data: make([f32], va.count),
234	            z_data: make([f32], va.count),
235	            count: va.count,
236	        };
237	
238	        for i = 0; i < va.count; i = i + 1 {
239	            result.x_data[i] = fclamp(va.x_data[i], min, max);
240	            result.y_data[i] = fclamp(va.y_data[i], min, max);
241	            result.z_data[i] = fclamp(va.z_data[i], min, max);
242	        }
243	
244	        return result;
245	    }
246	
247	    // threshold_vectors: 임계값에 따른 벡터 필터링
248	    // 크기가 threshold 이상인 벡터만 유지
249	    func threshold_vectors(va: *Vector3DArray, threshold: f32) -> Vector3DArray {
250	        let result = Vector3DArray {
251	            x_data: make([f32], va.count),
252	            y_data: make([f32], va.count),
253	            z_data: make([f32], va.count),
254	            count: 0,
255	        };
256	
257	        for i = 0; i < va.count; i = i + 1 {
258	            let vx = va.x_data[i];
259	            let vy = va.y_data[i];
260	            let vz = va.z_data[i];
261	
262	            let magnitude_sq = vx * vx + vy * vy + vz * vz;
263	            let threshold_sq = threshold * threshold;
264	
265	            if magnitude_sq >= threshold_sq {
266	                result.x_data[result.count] = vx;
267	                result.y_data[result.count] = vy;
268	                result.z_data[result.count] = vz;
269	                result.count = result.count + 1;
270	            }
271	        }
272	
273	        return result;
274	    }
275	
276	    // lerp_vectors: 벡터 선형 보간 (분기 없음)
277	    func lerp_vectors(va: *Vector3DArray, vb: *Vector3DArray, t: f32) -> Vector3DArray {
278	        let result = Vector3DArray {
279	            x_data: make([f32], va.count),
280	            y_data: make([f32], va.count),
281	            z_data: make([f32], va.count),
282	            count: va.count,
283	        };
284	
285	        for i = 0; i < va.count; i = i + 1 {
286	            result.x_data[i] = mix(va.x_data[i], vb.x_data[i], t);
287	            result.y_data[i] = mix(va.y_data[i], vb.y_data[i], t);
288	            result.z_data[i] = mix(va.z_data[i], vb.z_data[i], t);
289	        }
290	
291	        return result;
292	    }
293	}
